export function checkGateLabels({ gates = [], manifest = null, texts = [], demoTables = [] } = {}) {
  const hits = [];''',''' *   `texts` entries default to rules ["L3", "L4"]; the envelope README is passed with ["L3"] (ADR-0073 §6 scope).
